/// <returns>TransDate</returns>
protected TransDate initialActivationDate()
{
    TransDate  activateDate = next initialActivationDate();
    CostingVersion    costingVersion = CostingVersion::find(this.VersionId);

    if (costingVersion.AVAActivationDate != datenull())
    {
        activateDate = costingVersion.AVAActivationDate;
    }
    return activateDate;
}
